                //#endregion Load
                //#region Validace
                validateEmail() {
                    const content = this;
                    const field = content.findFields("misto_pod");
                    const value = field.gfield("getValue");
                    const def = $.Deferred();
                    //má hodnotu a je delší
                    if (value != null && value.length >= 3) {
                        const guid = Gordic.Utils.generateGuid();
                        content.beginOperation({ id: guid });
                        content
                            .call("KontrolaElementu", {
                            element: '<cmn:Email xmlns:cmn="urn:cz:mvcr:isoss:schemas:Common:v1">' + value.trim() + "</cmn:Email>",
                        })
                            .then((result) => {
                            if (result !== "") {
                                field.gfield("setError", {
                                    message: "jres:34900281", //RC 34900281 : E-mailová adresa elektronické podatelny je špatně zadána.
                                    errorType: "error",
                                });
                                def.resolve(false);
                            }
                            else
                                field.gfield("resetErrors");
                            def.resolve(true);
                        })
                            .always(() => {
                            content.endOperation(guid);
                        });
                    }
                    else
                        def.resolve(true);
                    return def.promise();
                }
                validateObory() {
                    const Content = this;
                    const view = Content.gridObory.ggrid("getView");
                    if (view.getCount("data") === 0) {
                        Content.gridObory.ggrid("setErrors", [{ message: "jres:34900287", stopping: true }]); //RC 34900287 : Není vybrán alespoň jeden obor služby.
                        return false;
                    }
                    else
                        Content.gridObory.ggrid("setErrors", []);
                    return true;
                }
                showErrorDialog() {
                    const Content = this;
                    const gridOboryErrors = Content.gridObory.ggrid("getErrors");
                    let chyby = "";
                    const fields = [];
                    Content.findFields().each((i, element) => {
                        $(element)
                            .gfield("getErrors")
                            .forEach((err) => {
                            if (chyby !== "")
                                chyby += "\n";
                            chyby += "\t" + err.message;
                            fields.push(element.dataset.field);
                        });
                    });
                    gridOboryErrors.forEach((err) => {
                        if (chyby !== "")
                            chyby += "\n";
                        chyby += "\t" + err.message;
                        fields.push("grid");
                    });
                    if (fields.length === 1)
                        Content.setFocusOnError(fields[0]);
                    Content.dialogs
                        .warning("jres:34900292", "jres:34900293" + chyby, 400) //RC 34900293 : Kontrola údajů nalezla tyto chyby:;;
                        .on("close", () => {
                        Content.gridObory.find(".bottom-panel").find("button").find(".g-state-error").trigger("click");
                    });
                }
                isDetailValid(showResult = false) {
                    const content = this;
                    const def = $.Deferred();
                    content.findFields().gfield("validate");
                    content.validateEmail().then((isValid) => {
                        const oboryValid = content.validateObory();
                        let jazykyZkValid = true;
                        for (let i = 1; i <= content.MAX_JAZ_ZK_SKUPINY; i++) {
                            jazykyZkValid = jazykyZkValid && content.findForms("formZkSkupina" + i).gform("isValid");
                        }
                        let jazykyZnValid = true;
                        for (let i = 1; i <= content.MAX_JAZ_ZN_SKUPINY; i++) {
                            jazykyZnValid = jazykyZnValid && content.findForms("formZnSkupina" + i).gform("isValid");
                        }
                        const valid = isValid &&
                            content.findForms("formHlavicka").gform("isValid") &&
                            content.findForms("formDetail").gform("isValid") &&
                            content.findForms("formVyber").gform("isValid") &&
                            jazykyZkValid &&
                            jazykyZnValid &&
                            content.findForms("formOdbornost").gform("isValid") &&
                            content.findForms("formDobaUrcita").gform("isValid") &&
                            content.findForms("formMistoPodani").gform("isValid") &&
                            content.findForms("formAdresaPodani").gform("isValid") &&
                            content.findForms("formKontakt").gform("isValid") &&
                            oboryValid;
                        if (!valid)
                            content.showErrorDialog();
                        else if (showResult && valid)
                            content.dialogs.messageBox("jres:34900122", "jres:34900307", [GDlg.mbbOk], GDlg.mbiSuccess); //RC 34900307 : Služební místo je v pořádku.
                        def.resolve(valid);
                    });
                    return def.promise();
                }
