                updateSaveButton() {
                    const content = this;
                    const isChange = content.findForms("formHlavicka").gform("hasChanged") ||
                        content.findForms("formDetail").gform("hasChanged") ||
                        content.findForms("formVyber").gform("hasChanged") ||
                        content.findForms("formZkSkupina1").gform("hasChanged") ||
                        content.findForms("formZkSkupina2").gform("hasChanged") ||
                        content.findForms("formZkSkupina3").gform("hasChanged") ||
                        content.findForms("formZnSkupina1").gform("hasChanged") ||
                        content.findForms("formZnSkupina2").gform("hasChanged") ||
                        content.findForms("formZnSkupina3").gform("hasChanged") ||
                        content.findForms("formOdbornost").gform("hasChanged") ||
                        content.findForms("formDobaUrcita").gform("hasChanged") ||
                        content.findForms("formMistoPodani").gform("hasChanged") ||
                        content.findForms("formAdresaPodani").gform("hasChanged") ||
                        content.findForms("formKontakt").gform("hasChanged") ||
                        content.isChangeObory ||
                        content.isChangeOdbornost ||
                        content.isChangePrilohy;
                    content.actions.act_Save?.enabled(isChange);
                }
                //#region Save
                saveDtosJazyky() {
                    const content = this;
                    const list = [];
                    let skupinaZkCount = 1;
                    for (let i = 1; i <= content.MAX_JAZ_ZK_SKUPINY; i++) {
                        const formSkupina = content.findForms("formZkSkupina" + i);
                        if (formSkupina.length > 0 && formSkupina.gform("hasChanged")) {
                            let poradiCount = 1;
                            for (let i = 1; i <= content.MAX_JAZ_ZKOUSKY; i++) {
                                const jazykField = formSkupina.findFields("jazyk_kod" + i);
                                const urovenField = formSkupina.findFields("jazyk_uroven" + i);
                                if (jazykField.length > 0 && jazykField.gfield("hasValue") && urovenField.length > 0 && urovenField.gfield("hasValue")) {
                                    const jazykVal = jazykField.gfield("getValue");
                                    const urovenVal = urovenField.gfield("getValue");
                                    list.push({
                                        druh_jazyk: 0,
                                        skupina: skupinaZkCount,
                                        jazyk_poradi: poradiCount,
                                        jazyk_kod: jazykVal.kod_stjzk,
                                        jazyk_kod_txt: jazykVal.kod_stjzk_txt,
                                        jazyk_uroven: urovenVal,
                                        jazyk_uroven_txt: urovenVal,
                                    });
                                    poradiCount++;
                                }
                            }
                            skupinaZkCount++;
                        }
                    }
                    function prevodUrovenJazZnalosti(uroven) {
                        switch (uroven) {
                            case "A1":
                                return "1";
                            case "A2":
                                return "2";
                            case "B1":
                                return "3";
                            case "B2":
                                return "4";
                            case "C1":
                                return "5";
                            case "C2":
                                return "6";
                            default:
                                return null;
                        }
                    }
                    let skupinaZnCount = 1;
                    for (let i = 1; i <= content.MAX_JAZ_ZN_SKUPINY; i++) {
                        const formSkupina = content.findForms("formZnSkupina" + i);
                        if (formSkupina.length > 0 && formSkupina.gform("hasChanged")) {
                            let poradiCount = 1;
                            for (let i = 1; i <= content.MAX_JAZ_ZNALOSTI; i++) {
                                const jazykField = formSkupina.findFields("jazyk_kod" + i);
                                const urovenField = formSkupina.findFields("jazyk_uroven_txt" + i);
                                if (jazykField.length > 0 && jazykField.gfield("hasValue") && urovenField.length > 0 && urovenField.gfield("hasValue")) {
                                    const jazykVal = jazykField.gfield("getValue");
                                    const urovenVal = urovenField.gfield("getValue");
                                    list.push({
                                        druh_jazyk: 1,
                                        skupina: skupinaZnCount,
                                        jazyk_poradi: poradiCount,
                                        jazyk_kod: jazykVal.kod_stjzk,
                                        jazyk_kod_txt: jazykVal.kod_stjzk_txt,
                                        jazyk_uroven: prevodUrovenJazZnalosti(urovenVal.uroven_zcj),
                                        jazyk_uroven_txt: urovenVal.uroven_zcj,
                                    });
                                    poradiCount++;
                                }
                            }
                            skupinaZnCount++;
                        }
                    }
                    return list.length === 0 ? null : list;
                }
                //#endregion Save
                //#region Init forms, tabs, grids
