                prepocetPusobnosti(pusobnost) {
                    const content = this;
                    const fieldSamPus = content.findFields("proc_sam_pus");
                    const fieldManPus = content.findFields("proc_man_pus");
                    const fieldObsPus = content.findFields("proc_obs_pus");
                    const fieldPus = content.findFields("proc_pren_pus");
                    const samPus = parseDecimal(fieldSamPus.gfield("getValue") ?? 0);
                    const manPus = parseDecimal(fieldManPus.gfield("getValue") ?? 0);
                    const obsPus = parseDecimal(fieldObsPus.gfield("getValue") ?? 0);
                    //const pusobnost = parseDecimal(fieldPus.gfield("getValue") ?? 0);
                    let resPusobnost = new Decimal(0).plus(samPus).plus(manPus).plus(obsPus).minus(100);
                    if (resPusobnost.greaterThan(0)) {
                        if (pusobnost === Gordic.Per.WebControls.Pusobnost.samostatna) {
                            if (samPus.eq(100)) {
                                fieldManPus.gfield("setValue", 0);
                                fieldObsPus.gfield("setValue", 0);
                            }
                            else if (manPus.greaterThanOrEqualTo(resPusobnost)) {
                                fieldManPus.gfield("setValue", manPus.minus(resPusobnost));
                            }
                            else {
                                resPusobnost = resPusobnost.minus(manPus);
                                fieldManPus.gfield("setValue", 0);
                                if (obsPus.greaterThanOrEqualTo(resPusobnost)) {
                                    fieldObsPus.gfield("setValue", obsPus.minus(resPusobnost));
                                }
                                else {
                                    fieldObsPus.gfield("setValue", 0);
                                }
                            }
                        }
                        else if (pusobnost === Gordic.Per.WebControls.Pusobnost.manazerska) {
                            if (manPus.eq(100)) {
                                fieldSamPus.gfield("setValue", 0);
                                fieldObsPus.gfield("setValue", 0);
                            }
                            else if (samPus.greaterThanOrEqualTo(resPusobnost)) {
                                fieldSamPus.gfield("setValue", samPus.minus(resPusobnost));
                            }
                            else {
                                resPusobnost = resPusobnost.minus(samPus);
                                fieldSamPus.gfield("setValue", 0);
                                if (obsPus.greaterThanOrEqualTo(resPusobnost)) {
                                    fieldObsPus.gfield("setValue", obsPus.minus(resPusobnost));
                                }
                                else {
                                    fieldObsPus.gfield("setValue", 0);
                                }
                            }
                        }
                        else if (pusobnost === Gordic.Per.WebControls.Pusobnost.obsluzna) {
                            if (obsPus.eq(100)) {
                                fieldManPus.gfield("setValue", 0);
                                fieldSamPus.gfield("setValue", 0);
                            }
                            else if (samPus.greaterThanOrEqualTo(resPusobnost)) {
                                fieldManPus.gfield("setValue", samPus.minus(resPusobnost));
                            }
                            else {
                                resPusobnost = resPusobnost.minus(samPus);
                                fieldSamPus.gfield("setValue", 0);
                                if (manPus.greaterThanOrEqualTo(resPusobnost)) {
                                    fieldManPus.gfield("setValue", manPus.minus(resPusobnost));
                                }
                                else {
                                    fieldManPus.gfield("setValue", 0);
                                }
                            }
                        }
                        content.findFields("proc_pren_pus").gfield("setValue", 0);
                    }
                    else {
                        content.findFields("proc_pren_pus").gfield("setValue", resPusobnost.abs());
                    }
                }
