                                    addTextSpec("popis_dusevni", "0000BHR08ZMI");
                                    addTextSpec("popis_fyzicke", "0000BHR08ZND");
                                    addTextSpec("popis_prac_podminky", "0000BHR08ZKS");
                                    addTextSpec("popis_rizika", "0000BHR08ZLN");
                                    addTextSpec("popis_zvl_pripl", "0000BHR09X1G");
                                    addTextSpec("popis_ztis_pros", "0000BHR09X2B");
                                    addTextSpec("popis_noc", "0000BHR09X36");
                                    addTextSpec("popis_vzdelani", "0000BHR09MP9");
                                    addTextSpec("popis_zdravi", "0000BHR09X41");
