                                        odpovednost: content.jeZmenaOdpovednost ? content.gridHmotOdp.ggrid("getView").getDataRows(false, "data") : null,
                                        zastup: saveDetailDto.ixs_hci_ksm !== "0000BHR0980G" && content.jeZmenaZastupSym ? content.saveZastupSymDto() : null,
                                        oborySluzby: saveDetailDto.ixs_hci_ksm === "0000BHR0980G" && content.jeZmenaOborySluzby ? content.saveOborySluzbyDto() : null,
                                        slozkyPlatu: content.jeZmenaSlozkyPlatu ? content.gridSlozkyPlatu.ggrid("getView").getDataRows(false, "data") : null,
                                        agendy: content.jeZmenaAgendy ? content.gridAgendy.ggrid("getView").getDataRows(false, "data") : null,
                                        vzdelani: listVzdelaniSave,
                                        text_specifikace: textSpecifikace,
                                        odbor_pozadavky: odbPoz,
