                    content.actions.add({
                        name: "act_Load_SYM_detail",
                        enabled: true, //(Content.Action !== EnumActions.Detail),
                        run: () => {
                            const guid = Gordic.Utils.generateGuid();
                            content.beginOperation({ id: guid, text: "jres:34900001" }); //RC 34900001 : Načítání detailu SYM
                            content.isl.Sym.listZmeny({
                                filters: {
                                    ixs_vos: content.Action === WebClient.EnumActions.New ? content.dtoOce.ixs_vos : content.dtoSym.ixs_vos,
                                    ixs_sym: content.Action === WebClient.EnumActions.New && content.IxsSym != null ? content.IxsSym : content.dtoSym.ixs_sym,
                                    aktivita: true,
                                },
                            })
                                .getData()
                                .done((data) => {
                                if (data != null && data.length > 0) {
                                    content.listDtoZmenySym = data;
                                    content.listDtoZmenySym = data;
                                    /*if (data[0].org_pri != null)
                                    data[0].org_pri = data[0].org_pri?.trim();*/
                                    content.findFields("form: form_info").gfield("model", "apply", data[0], { initialValues: true });
                                    content.findFields("form: form_prac_pom").gfield("model", "apply", data[0], { initialValues: true });
                                    content.findFields("form: form_potreb_vzdelani").gfield("model", "apply", data[0], { initialValues: true });
                                    content.findFields("form: form_specifikace").gfield("model", "apply", data[0], { initialValues: true });
                                    content.findFields("ixs_hci_kzam").gfield("model", "apply", { ixs_hci_kzam: data[0].ixs_hci_kzam }, { initialValues: true });
                                    content.findForms("form_info").findFields("dat_zmena").gfield("setInitial", new Date());
                                    content
                                        .findForms("form_info")
                                        .findFields("ixs_hci_kvsm")
                                        .gfield("option", "disabled", !data[0].ixs_hci_prvp || data[0].ixs_hci_prvp !== "0000BHR07MPZ" || content.Action === WebClient.EnumActions.Detail);
                                    content.dtoZmenySym = data[0];
                                    content.jeStatZamestnanec = content.dtoZmenySym.ixs_hci_ksm === "0000BHR0980G";
                                    content.jeSluzba = content.dtoZmenySym.ixs_hci_ksm === "0000BHR03TYT";
                                    content.jePracPomer = content.dtoZmenySym.ixs_hci_ksm === "0000BHR03TXY";
                                }
                            })
                                .fail((xhr, type, vobj) => {
                                if (type === "exception") {
                                    if (vobj.baseType === "Gordic.General.GNonFatalException" || vobj.baseType === "Gordic.General.GArgumentNullException") {
                                        vobj.handled = true;
                                        //that.showFlash(vobj.baseMessage, "error");
                                        Gordic.Per.WebControls.showError(this, "jres:34900002", vobj.baseMessage); //RC 34900002 : Načtení detailu SYM
                                    }
                                }
                            })
                                .always(() => {
                                content.endOperation(guid);
                            });
                            //}
                        },
                    });
                    //#region Funkce - činnost
                    content.actions.add({
                        name: "act_Load_Cinnosti",
                        caption: "jres:29120025", //RC 29120025 : Občerstvit
                        enabled: true, //(Content.Action !== EnumActions.Detail),
                        tooltip: "jres:29120025", //RC 29120025 : Občerstvit
                        icon: "gi-refresh",
                        run: () => {
                            const guid = Gordic.Utils.generateGuid();
                            content.beginOperation({ id: guid, text: "jres:34900003" }); //RC 34900003 : Načítání činnosti dle katalogu prací
                            content.isl.Sym.listCinnosti({
                                filters: {
                                    aktivita: "100", //that.aktivita,//that.filterAktivni,
                                    ixs_sym: content.Action === WebClient.EnumActions.New && content.IxsSym != null ? content.IxsSym : content.dtoSym.ixs_sym,
                                    poradi: null,
                                    poradi_ver: null,
                                },
                            })
                                .getData()
                                .done((data) => {
                                //debugger;
                                if (data != null && data.length > 0) {
                                    //filtrování dat na aktuální poradi_ver
                                    const maxPoradi = data.reduce((prev, current) => {
                                        return prev.poradi_ver > current.poradi_ver ? prev : current;
                                    });
                                    const filterData = data.filter((e) => e.poradi_ver == maxPoradi.poradi_ver);
                                    //content.listDtoCinnostiSym = filterData;
                                    content.jeZmenaCinnosti = false;
                                    content.gridCinnosti.ggrid("setData", new Gordic.Data.View(filterData, { key: "ixs_sym,poradi" }));
                                    content.dtoCinnostiSym = maxPoradi /*filterData[0]*/;
                                    content.actions.act_Delete_Cinnost.enabled(filterData != null && filterData.length > 0 && content.Action !== WebClient.EnumActions.Detail);
                                }
                            })
                                .fail((xhr, type, vobj) => {
                                if (type === "exception") {
                                    if (vobj.baseType === "Gordic.General.GNonFatalException" || vobj.baseType === "Gordic.General.GArgumentNullException") {
                                        vobj.handled = true;
                                        content.showFlash(vobj.baseMessage, "error");
                                    }
                                }
                            })
                                .always(() => {
                                content.endOperation(guid);
                            });
                            //}
                        },
                    });
                    content.actions.add({
                        name: "act_New_Cinnost",
                        enabled: content.Action !== WebClient.EnumActions.Detail,
                        caption: "jres:29120019", //RC 29120019 : Nová
                        tooltip: "jres:32730312",
                        icon: "gi-plus",
                        run: () => {
                            //RC 32730312 : Přidá novou činnost dle katalogu prací vázanou na SYM
                            if (content.jeStatZamestnanec && content.ParametrGinIsossReadyBool) {
                                //TODO:
                                //content.dialogs.simpleForm("Detail správní činnosti a oboru služby",
                                //    new Forms.Form({ name: "formSpravniCinnost" })
                                //        .addRow({ label: "Správní činnost", required: true })
                                //        .addField("gselectbox", Prefabs.Select.gCisReaderPesckpr(), { //TODO asi vlastní prefab
                                //            name: "ixs_hci_kpr",
                                //            model:"ixs_hci_kpr=ixs_hci_kpr,kpr_kod=kod_kpr"
                                //        })
                                //        .addRow()
                                //)
                            }
                            else {
                                content.call("GetDruhTabulky").then((druhTabulkyVychozi) => {
                                    const selectWindow = content.dialogs.showModalWindow("Gordic.Pes.WebClient.GDetailCinnostiTab", {
                                        taskId: content.taskId,
                                        uid: "DetailCinnostiTab#",
                                        Action: WebClient.EnumActions.New,
                                        DruhTab: druhTabulkyVychozi,
                                        PlatTrida: content.findFields("plat_trida").gfield("getValue")?.plat_trida,
                                        Datum: content.findFields("dat_zmena").gfield("getValue"),
                                        JeSluzMisto: content.jeStatZamestnanec,
                                        dtoPovolaniSym: content.listDtoPovolaniSym,
                                    }, {
                                        width: 800, //, height: 400
                                    });
                                    const windowContent = $.content(selectWindow);
                                    windowContent.close((data) => {
                                        //debugger;
                                        if (data != null) {
                                            //if (content.listDtoCinnostiSym == undefined) content.listDtoCinnostiSym = [];
                                            const view = content.gridCinnosti.ggrid("getView");
                                            data.list.forEach((item) => {
                                                if (item.ixs_sym == null || item.ixs_sym != content.dtoSym.ixs_sym) {
                                                    item.ixs_sym = content.dtoSym.ixs_sym;
                                                }
                                                item.poradi = content.poradiCinnost--;
                                                item.poradi_ver = null;
                                                //content.listDtoCinnostiSym.push(item);
                                                content.jeZmenaCinnosti = true;
                                                view.updateData(item, "add");
                                            });
                                        }
                                    });
                                });
                            }
                        },
                    });
