                    let enable = false;
                    content.formNames.forEach((form) => {
                        enable = enable || content.findForms(form).gform("hasChanged");
                    });
                    content.actions.actSave?.enabled(enable || content.jeZmenaKomise || content.jeZmenaUchazeci);
